1	#!/usr/bin/env node
2	// fleet — operator CLI. Exit codes: 0 ok, 1 failure, 2 usage.
3	import { parseArgs } from 'node:util';
4	import { spawnSync } from 'node:child_process';
5	import fs from 'node:fs';
6	import path from 'node:path';
7	import { fileURLToPath } from 'node:url';
8	import { validateManifest, validateWorkOrder, jobStates } from '../validate.mjs';
9	import { request, describeTarget, type DaemonResponse } from './client.ts';
10	
11	const EXIT_OK = 0;
12	const EXIT_FAILURE = 1;
13	const EXIT_USAGE = 2;
14	
15	const HELP = `fleet — run coding-agent jobs in containers in your own cloud
16	
17	Usage: fleet <command> [options]
18	
19	Commands:
20	  init [--existing]                        Scaffold .fleet/ (manifest, setup.sh, out/)
21	  lint [path]                              Validate manifest (+ .fleet/orders/*.json), no daemon
22	  delegate <target> [--mode m] [--finish rung] [--manifest path] [--watch]
23	                                           Build a work order and POST it to the daemon
24	                                           (--watch: follow the job, answer decisions from stdin)
25	  status [jobId]                           List jobs (blocked first) or show one job
26	  logs <jobId> [--after seq]               Dump job events
27	  attach <jobId> [--answer]                Follow job events until done/cancelled
28	                                           (--answer: respond to decisions from stdin)
29	  answer <jobId> [--option id] [--text s]  Answer a blocked job's decision
30	  cancel <jobId>                           Cancel a job
31	  doctor                                   Environment checks (Phase 1 stub)
32	  version                                  Print version and exit
33	
34	Flags:
35	  --version                                Print version and exit
36	
37	Daemon address: FLEET_DAEMON_URL, or unix socket at $FLEET_HOME/daemon.sock (default ~/.fleet).`;
38	
39	class UsageError extends Error {}
40	class CliError extends Error {}
41	
42	// jobStates ships in this repo as schemas/job-states.json; shape covered by test/schemas.test.mjs.
43	const TERMINAL_STATES: string[] = jobStates.terminal;
44	
45	function fail(message: string): never {
46	  throw new CliError(message);
47	}
48	
49	function errorMessage(err: unknown): string {
50	  return err instanceof Error ? err.message : String(err);
51	}
52	
53	function readJsonFile(file: string, what: string): unknown {
54	  let raw: string;
55	  try {
56	    raw = fs.readFileSync(file, 'utf8');
57	  } catch {
58	    fail(`${what} not found: ${file}`);
59	  }
60	  try {
61	    return JSON.parse(raw);
62	  } catch (err) {
63	    fail(`${what} is not valid JSON (${file}): ${errorMessage(err)}`);
64	  }
65	}
66	
67	type AjvError = { instancePath: string; message?: string };
68	
69	function formatFindings(file: string, errors: AjvError[]): string[] {
70	  return errors.map((e) => `${file}: ${e.instancePath || '/'} ${e.message ?? 'invalid'}`);
71	}
72	
73	// ---------- init ----------
74	
75	const SETUP_STUB = `#!/usr/bin/env sh
76	# Fleet setup script: everything the job image needs before the harness runs
77	# (dependencies, build, seed data). Runs with unrestricted egress.
78	set -eu
79	
80	echo "fleet setup: replace this stub with your project's setup steps (e.g. npm ci)"
81	`;
82	
83	const BROWNFIELD_GUIDANCE = `Brownfield init: this repo already has a life outside Fleet.
84	Extract .fleet/setup.sh from your real "new laptop" steps — the commands you
85	actually run to make a fresh clone workable (install deps, build, seed, env).
86	Then edit .fleet/manifest.json: real repo URL, env.vars your project reads,
87	workspace.sync for gitignored runtime config, and a pickup gate that proves
88	the workspace is ready before any model spend.`;
89	
90	function initManifest(): unknown {
91	  return {
92	    version: 1,
93	    setup: { image: 'node:22', script: '.fleet/setup.sh' },
94	    workspace: { repo: 'git@github.com:acme/example-app.git', strategy: 'branch-per-job' },
95	    harness: {
96	      cli: 'claude-code',
97	      commands: [{ path: '.claude/commands/dev-sprint.md', critic: 'code-reviewer' }],
98	    },
99	    gates: { pickup: 'node .fleet/check-ready.js', default_finish: 'merge-ready' },
100	  };
101	}
102	
103	// Runtime and per-deployment artifacts never belong in the user's repo:
104	// out/ is the job's decision/answer/report channel; infra/ holds generated
105	// terraform + local state + the per-deployment fleet-config.json (two people
106	// on the same repo can point at different infra).
107	const FLEET_GITIGNORE = `out/
108	infra/
109	`;
110	
111	function cmdInit(args: string[]): number {
112	  const { values } = parseCommand(args, { existing: { type: 'boolean' } }, 0, 0);
113	  const existing = values.existing === true;
114	  const fleetDir = path.resolve('.fleet');
115	  const manifestPath = path.join(fleetDir, 'manifest.json');
116	  const setupPath = path.join(fleetDir, 'setup.sh');
117	  const gitkeepPath = path.join(fleetDir, 'out', '.gitkeep');
118	
119	  if (fs.existsSync(manifestPath)) {
120	    fail(`refusing to overwrite existing ${manifestPath} — remove it first if you really want a fresh scaffold`);
121	  }
122	  const setupExists = fs.existsSync(setupPath);
123	  if (setupExists && !existing) {
124	    fail(`refusing to overwrite existing ${setupPath} — rerun with --existing to keep it`);
125	  }
126	
127	  fs.mkdirSync(path.join(fleetDir, 'out'), { recursive: true });
128	  fs.writeFileSync(manifestPath, `${JSON.stringify(initManifest(), null, 2)}\n`);
129	  if (!setupExists) fs.writeFileSync(setupPath, SETUP_STUB, { mode: 0o755 });
130	  if (!fs.existsSync(gitkeepPath)) fs.writeFileSync(gitkeepPath, '');
131	  const gitignorePath = path.join(fleetDir, '.gitignore');
132	  if (!fs.existsSync(gitignorePath)) fs.writeFileSync(gitignorePath, FLEET_GITIGNORE);
133	
134	  console.log(`wrote ${manifestPath}`);
135	  if (setupExists) console.log(`kept existing ${setupPath}`);
136	  else console.log(`wrote ${setupPath}`);
137	  console.log(`wrote ${gitkeepPath}`);
138	  if (existing) console.log(`\n${BROWNFIELD_GUIDANCE}`);
139	  else console.log('\nEdit .fleet/manifest.json (repo URL, pickup gate) and .fleet/setup.sh before delegating.');
140	  return EXIT_OK;
141	}
