143	// ---------- lint ----------
144	
145	function cmdLint(args: string[]): number {
146	  const { positionals } = parseCommand(args, {}, 0, 1);
147	  const manifestPath = positionals[0] ?? path.join('.fleet', 'manifest.json');
148	  const findings: string[] = [];
149	  let checked = 0;
150	
151	  try {
152	    const manifest = readJsonFile(manifestPath, 'manifest');
153	    checked += 1;
154	    const { ok, errors } = validateManifest(manifest);
155	    if (!ok) findings.push(...formatFindings(manifestPath, errors));
156	  } catch (err) {
157	    if (err instanceof CliError) findings.push(err.message);
158	    else throw err;
159	  }
160	
161	  const ordersDir = path.join('.fleet', 'orders');
162	  if (fs.existsSync(ordersDir)) {
163	    const orderFiles = fs.readdirSync(ordersDir).filter((f) => f.endsWith('.json')).sort();
164	    for (const name of orderFiles) {
165	      const file = path.join(ordersDir, name);
166	      try {
167	        const order = readJsonFile(file, 'work order');
168	        checked += 1;
169	        const { ok, errors } = validateWorkOrder(order);
170	        if (!ok) findings.push(...formatFindings(file, errors));
171	      } catch (err) {
172	        if (err instanceof CliError) findings.push(err.message);
173	        else throw err;
174	      }
175	    }
176	  }
177	
178	  for (const line of findings) console.error(line);
179	  if (findings.length > 0) return EXIT_FAILURE;
180	  console.log(`lint ok: ${checked} file(s) valid`);
181	  return EXIT_OK;
182	}
