184	// ---------- delegate ----------
185	
186	type Manifest = {
187	  workspace?: { repo?: string; sync?: string[] };
188	  env?: { vars?: string[] };
189	  gates?: { default_finish?: string };
190	};
191	
192	/** git stdout in cwd, or undefined on any failure. */
193	function gitValue(args: string[]): string | undefined {
194	  const res = spawnSync('git', args, { encoding: 'utf8' });
195	  const out = res.status === 0 ? res.stdout.trim() : '';
196	  return out === '' ? undefined : out;
197	}
198	
199	type ModePreset = {
200	  mode: string;
201	  authority: unknown;
202	  finish?: string;
203	  report?: string;
204	};
205	
206	function loadPresets(): Record<string, ModePreset> {
207	  const raw = readJsonFile(fileURLToPath(new URL('../../presets/modes.json', import.meta.url)), 'mode presets');
208	  // Repo-shipped presets/modes.json; shape enforced by test/presets.test.mjs.
209	  const presets = raw as { modes: Record<string, ModePreset> };
210	  if (typeof presets.modes !== 'object' || presets.modes === null) fail('mode presets file has no "modes" object');
211	  return presets.modes;
212	}
213	
214	async function cmdDelegate(args: string[]): Promise<number> {
215	  const { values, positionals } = parseCommand(
216	    args,
217	    { mode: { type: 'string' }, finish: { type: 'string' }, manifest: { type: 'string' }, watch: { type: 'boolean' } },
218	    1,
219	    1,
220	  );
221	  const target = positionals[0];
222	  const manifestPath = typeof values.manifest === 'string' ? values.manifest : path.join('.fleet', 'manifest.json');
223	
224	  const rawManifest = readJsonFile(manifestPath, 'manifest');
225	  const manifestCheck = validateManifest(rawManifest);
226	  if (!manifestCheck.ok) {
227	    for (const line of formatFindings(manifestPath, manifestCheck.errors)) console.error(line);
228	    return EXIT_FAILURE;
229	  }
230	  // Safe: validated against manifest.schema.json just above.
231	  const manifest = rawManifest as Manifest;
232	
233	  const modes = loadPresets();
234	  const modeName = typeof values.mode === 'string' ? values.mode : 'implement';
235	  const preset = modes[modeName];
236	  if (!preset) fail(`unknown mode "${modeName}" — available: ${Object.keys(modes).join(', ')}`);
237	
238	  const flagFinish = typeof values.finish === 'string' ? values.finish : undefined;
239	  const workOrder = {
240	    mode: preset.mode,
241	    target,
242	    finish: flagFinish ?? preset.finish ?? manifest.gates?.default_finish ?? 'merge-ready',
243	    authority: preset.authority,
244	    report: preset.report ?? 'status-first',
245	  };
246	  const orderCheck = validateWorkOrder(workOrder);
247	  if (!orderCheck.ok) {
248	    for (const line of formatFindings('work order', orderCheck.errors)) console.error(line);
249	    return EXIT_FAILURE;
250	  }
251	
252	  const sync: Record<string, string> = {};
253	  for (const rel of manifest.workspace?.sync ?? []) {
254	    const file = path.resolve(rel);
255	    if (!fs.existsSync(file)) fail(`missing sync file: ${rel} (listed in workspace.sync, not found in ${process.cwd()})`);
256	    sync[rel] = fs.readFileSync(file).toString('base64');
257	  }
258	
259	  const env: Record<string, string> = {};
260	  for (const name of manifest.env?.vars ?? []) {
261	    const value = process.env[name];
262	    if (value === undefined) fail(`missing env var: ${name} (listed in manifest env.vars, not set in this shell)`);
263	    env[name] = value;
264	  }
265	
266	  // Workspace git (#2): resolve the repo URL at dispatch — including the
267	  // "origin" sentinel — and ship the operator's git identity. The runner
268	  // activates git mode only when FLEET_GIT_URL is present.
269	  const repoUrl = manifest.workspace?.repo;
270	  if (typeof repoUrl === 'string' && repoUrl !== '') {
271	    const resolved = repoUrl === 'origin' ? gitValue(['remote', 'get-url', 'origin']) : repoUrl;
272	    if (!resolved) fail('workspace.repo is "origin" but this checkout has no origin remote');
273	    const name = gitValue(['config', 'user.name']);
274	    const email = gitValue(['config', 'user.email']);
275	    if (!name || !email) fail('git identity missing: set git config user.name and user.email — job commits are authored as you');
276	    env.FLEET_GIT_URL = resolved;
277	    env.FLEET_GIT_NAME = name;
278	    env.FLEET_GIT_EMAIL = email;
279	  }
280	
281	  const res = await daemonCall('POST', '/jobs', { workOrder, manifest, env, sync });
282	  if (res.status !== 201) return daemonFailure(res, 'delegate');
283	  // Daemon API contract: POST /jobs → 201 {job}.
284	  const created = res.json as { job: { id: string; state: string } };
285	  console.log(`${created.job.id} ${created.job.state}`);
286	  if (values.watch === true) return followJob(created.job.id, true);
287	  return EXIT_OK;
288	}
