290	// ---------- job event rendering ----------
291	
292	type FleetEvent = {
293	  seq: number;
294	  type: string;
295	  state?: string;
296	  reason?: string;
297	  marker?: string;
298	  text?: string;
299	  value?: number;
300	  id?: string;
301	  question?: string;
302	  options?: Array<{ id: string; label?: string; recommended?: boolean }>;
303	  decision?: string;
304	  option?: string;
305	  by?: string;
306	  rung?: string;
307	  minutes?: number;
308	  report?: { status?: string; next_action?: string };
309	};
310	
311	function formatEvent(event: FleetEvent): string {
312	  const head = `[${event.seq}] ${event.type}`;
313	  switch (event.type) {
314	    case 'state': {
315	      const extras = [event.reason && `reason=${event.reason}`, event.marker && `marker=${event.marker}`]
316	        .filter(Boolean)
317	        .join(' ');
318	      return `${head} ${event.state}${extras ? ` ${extras}` : ''}`;
319	    }
320	    case 'phase':
321	    case 'think':
322	    case 'log':
323	      return `${head} ${event.text ?? ''}`;
324	    case 'progress':
325	      return `${head} ${Math.round((event.value ?? 0) * 100)}%`;
326	    case 'decision': {
327	      const options = (event.options ?? [])
328	        .map((o) => `  - ${o.id}${o.recommended ? ' (recommended)' : ''}${o.label ? `: ${o.label}` : ''}`)
329	        .join('\n');
330	      return `${head} ${event.id}: ${event.question}\n${options}\n  answer with: fleet answer <jobId> --option <id> [--text s]`;
331	    }
332	    case 'answer':
333	      return `${head} ${event.decision} → ${event.option ?? '(free text)'}${event.text ? ` "${event.text}"` : ''}${event.by ? ` by ${event.by}` : ''}`;
334	    case 'settle':
335	      return `${head} rung=${event.rung ?? '?'} status=${event.report?.status ?? '?'}${event.report?.next_action ? ` next: ${event.report.next_action}` : ''}`;
336	    default:
337	      return `${head} ${JSON.stringify({ ...event, seq: undefined, type: undefined })}`;
338	  }
339	}
340	
341	function printEventLine(line: string): FleetEvent | undefined {
342	  try {
343	    const event: FleetEvent = JSON.parse(line);
344	    console.log(formatEvent(event));
345	    return event;
346	  } catch {
347	    console.log(line); // never crash on a malformed daemon line
348	    return undefined;
349	  }
350	}
