352	// ---------- daemon-backed commands ----------
353	
354	async function daemonCall(
355	  method: string,
356	  reqPath: string,
357	  body?: unknown,
358	  onLine?: (line: string) => void,
359	): Promise<DaemonResponse> {
360	  try {
361	    return await request(method, reqPath, body, { onLine });
362	  } catch (err) {
363	    fail(`cannot reach daemon at ${describeTarget()}: ${errorMessage(err)}`);
364	  }
365	}
366	
367	function daemonFailure(res: DaemonResponse, what: string): number {
368	  // Daemon API contract: schema failures return {errors: [...ajv error objects]};
369	  // non-schema failures (409 not-blocked, 422 bad option) return {error: string}.
370	  const body = res.json as { errors?: AjvError[]; error?: string } | undefined;
371	  if (body && Array.isArray(body.errors)) {
372	    for (const line of formatFindings(what, body.errors)) console.error(line);
373	  } else if (body && typeof body.error === 'string') {
374	    console.error(`${what} failed: ${body.error}`);
375	  } else {
376	    console.error(`${what} failed: daemon returned ${res.status}${res.body ? ` ${res.body.trim()}` : ''}`);
377	  }
378	  return EXIT_FAILURE;
379	}
380	
381	type Job = {
382	  id: string;
383	  state: string;
384	  marker?: string;
385	  workOrder?: { mode?: string; target?: string };
386	  updatedAt?: string;
387	};
388	
389	function formatJob(job: Job): string {
390	  const state = typeof job.marker === 'string' ? `${job.state}(${job.marker})` : job.state;
391	  const mode = job.workOrder?.mode ?? '?';
392	  const target = job.workOrder?.target ?? '?';
393	  const updated = typeof job.updatedAt === 'string' ? `  updated=${job.updatedAt}` : '';
394	  return `${job.id}  ${state}  mode=${mode}  target=${target}${updated}`;
395	}
396	
397	async function cmdStatus(args: string[]): Promise<number> {
398	  const { positionals } = parseCommand(args, {}, 0, 1);
399	  const jobId = positionals[0];
400	  if (jobId === undefined) {
401	    const res = await daemonCall('GET', '/jobs');
402	    if (res.status !== 200) return daemonFailure(res, 'status');
403	    // Daemon API contract: GET /jobs → 200 {jobs: [...]}.
404	    const listed = res.json as { jobs: Job[] };
405	    if (listed.jobs.length === 0) console.log('no jobs');
406	    for (const job of listed.jobs) console.log(formatJob(job));
407	    return EXIT_OK;
408	  }
409	  const res = await daemonCall('GET', `/jobs/${encodeURIComponent(jobId)}`);
410	  if (res.status !== 200) return daemonFailure(res, 'status');
411	  // Daemon API contract: GET /jobs/:id → 200 {job}.
412	  const shown = res.json as { job: Job };
413	  console.log(formatJob(shown.job));
414	  return EXIT_OK;
415	}
416	
417	async function cmdLogs(args: string[]): Promise<number> {
418	  const { values, positionals } = parseCommand(args, { after: { type: 'string' } }, 1, 1);
419	  const jobId = positionals[0];
420	  const after = typeof values.after === 'string' ? values.after : undefined;
421	  if (after !== undefined && !/^-?\d+$/.test(after)) throw new UsageError('--after takes an integer sequence number');
422	  const query = after === undefined ? '' : `?after=${after}`;
423	  const res = await daemonCall('GET', `/jobs/${encodeURIComponent(jobId)}/events${query}`, undefined, printEventLine);
424	  if (res.status !== 200) return daemonFailure(res, 'logs');
425	  return EXIT_OK;
426	}
