428	/**
429	 * Read one answer line from stdin for a pending decision.
430	 * Grammar: "<option-id> [supplementary text]" | "text: <free text>" | "" (skip).
431	 */
432	async function readAnswerLine(prompt: string): Promise<{ option?: string; text?: string } | undefined> {
433	  const readline = await import('node:readline/promises'); // lazy: only in interactive watch mode
434	  const rl = readline.createInterface({ input: process.stdin, output: process.stderr });
435	  try {
436	    const line = (await rl.question(prompt)).trim();
437	    if (line === '') return undefined;
438	    if (line.startsWith('text:')) return { text: line.slice('text:'.length).trim() };
439	    const [option, ...restWords] = line.split(/\s+/);
440	    const text = restWords.join(' ');
441	    return text ? { option, text } : { option };
442	  } finally {
443	    rl.close();
444	  }
445	}
446	
447	/**
448	 * Follow a job to a terminal state, printing events. With answerMode, pending
449	 * decisions are answered from stdin between poll cycles. Watching is a view,
450	 * never a lifeline: disconnecting changes nothing for the job.
451	 */
452	async function followJob(jobId: string, answerMode: boolean): Promise<number> {
453	  let after: number | undefined;
454	  let terminal = false;
455	  let pendingDecision: FleetEvent | undefined;
456	
457	  while (!terminal) {
458	    const query = after === undefined ? '?follow=1' : `?after=${after}&follow=1`;
459	    const res = await daemonCall('GET', `/jobs/${encodeURIComponent(jobId)}/events${query}`, undefined, (line) => {
460	      const event = printEventLine(line);
461	      if (!event) return;
462	      if (typeof event.seq === 'number') after = event.seq;
463	      if (event.type === 'decision') pendingDecision = event;
464	      if (event.type === 'answer') pendingDecision = undefined; // answered elsewhere
465	      if (event.type === 'state' && typeof event.state === 'string' && TERMINAL_STATES.includes(event.state)) {
466	        terminal = true;
467	      }
468	    });
469	    if (res.status !== 200) return daemonFailure(res, 'attach');
470	    if (!terminal && answerMode && pendingDecision) {
471	      const ids = (pendingDecision.options ?? []).map((o) => o.id).join(' | ');
472	      const answer = await readAnswerLine(`answer [${ids}] ("<id> [note]" or "text: ..." or empty to keep waiting): `);
473	      if (answer) {
474	        const posted = await daemonCall('POST', `/jobs/${encodeURIComponent(jobId)}/answer`, answer);
475	        if (posted.status !== 200) daemonFailure(posted, 'answer'); // print and keep watching
476	        else pendingDecision = undefined;
477	      }
478	    }
479	  }
480	  return EXIT_OK;
481	}
482	
483	async function cmdAttach(args: string[]): Promise<number> {
484	  const { values, positionals } = parseCommand(args, { answer: { type: 'boolean' } }, 1, 1);
485	  return followJob(positionals[0], values.answer === true);
486	}
