496	  const body: Record<string, string> = {};
497	  if (typeof values.option === 'string') body.option = values.option;
498	  if (typeof values.text === 'string') body.text = values.text;
499	  if (Object.keys(body).length === 0) throw new UsageError('answer requires --option <id> and/or --text <s>');
500	  const res = await daemonCall('POST', `/jobs/${encodeURIComponent(jobId)}/answer`, body);
501	  if (res.status !== 200) return daemonFailure(res, 'answer');
502	  console.log(`answered ${jobId}`);
503	  return EXIT_OK;
504	}
